"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["6766"],{4807(e,n,t){t.r(n),t.d(n,{metadata:()=>o,default:()=>l,frontMatter:()=>r,contentTitle:()=>s,toc:()=>u,assets:()=>c});var o=JSON.parse('{"id":"explain/faq","title":"FAQ","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/explain/faq.md","sourceDirName":"explain","slug":"/explain/faq","permalink":"/personal-av-docs/docs/explain/faq","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/explain/faq.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"FAQ","sidebar_label":"FAQ","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/faq","format":"md"}}'),a=t(4848),i=t(8453);let r={title:"FAQ",sidebar_label:"FAQ",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/faq",format:"md"},s,c={},u=[];function d(e){let n={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(n.p,{children:[":::note Edition\n",(0,a.jsx)(n.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(n.a,{href:"https://doc.airvantage.net/connectivity/faq",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsxs)(n.p,{children:["FAQ\nReferences\nAccount Management\nOrders\nBilling\nAdministration\nSubaccounts\nConnectivity Management\nDashboard\nMonitor\nConfigure\nAPI, Connectors & Other Services\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct page\nSearching...\nMatching results\nFAQ\nHow can I contact support?\nWhich browsers are supported by AirVantage?\nIs it possible to suspend the subscription from AirVantage?\nHow can I trigger the Test-Ready Mode?\nWhat is the difference between suspending and terminating a subscription?\nI cannot connect to the network with my Sierra Wireless SIM card / Ready-to-Connect device\nIs service active?\nIs the APN correct?\nAre SW Advanced SIM pre-requisites met?\nAre you roaming on an LTE-only network?\nI cannot activate my Verizon SIM card\nUsage is not reporting in the usage widgets\nI have ordered SIM cards but I haven\u2019t received them yet. What can I do?\nHow often do I get an invoice?\nI have lost an invoice. What can I do?\nHow can I check AirVantage or Connectivity services health?\nCan I use an API to manage my SIM cards?\nHave a question on Sierra Wireless Connectivity?\nPlease check this page and contact us if you don\u2019t find what you are looking for.\nHow can I contact support?\nOur support is available to answer your questions and concerns.\nYou can contact support directly from your AirVantage account\nOnce logged in, expand the user menu and select the\nNeed Help?\nlink or alternatively use the\nContact technical support\nlink from the start page of your AirVantage account at\n",(0,a.jsx)(n.a,{href:"https://eu.airvantage.net/accounts/",children:"https://eu.airvantage.net/accounts/"}),"\n.\nThis will direct you to a list of resources that can help you including how to contact the support.\nWhich browsers are supported by AirVantage?\nThe compatible web browsers are: Microsoft Edge, Mozilla Firefox, Google Chrome and Safari.\nIs it possible to suspend the subscription from AirVantage?\nYes, you can suspend some of your SIMs you don\u2019t use for a period of time to prevent them from generating traffic on the network.\nTo Suspend a SIM:\nFrom your AirVantage account, follow the\nManage your Connectivity\nlink\nSelect\nMonitor > Systems\nmenu\nSelect the SIMs you want to suspend\nClick the Suspend button\nHow can I trigger the Test-Ready Mode?\nTo benefit from the test ready mode, you simply need to activate the SIM on a Test Ready Mode compatible offer. For more details on Test Ready Mode, you can refer to\nthe Life Cycle section of the Monitor Reference page.\nWhat is the difference between suspending and terminating a subscription?\nWhen a SIM card is suspended the traffic to and from the SIM card is blocked. The monthly subscription fee still applies. The SIM can easily be resumed.\nTo terminate a SIM means that the SIM is decommissioned definitively from the network, there is no way to turn it back on.\nWhen a SIM is terminated, there is no more subscription cost associated with it.\nI cannot connect to the network with my Sierra Wireless SIM card / Ready-to-Connect device\nTypical causes for a unit being unable to connect to the network are listed below, with corrective action for each. If the actions below fail to fix the issue, please contact our support team for further investigation.\nIs service active?\nConnectivity service may not yet activated for your SIM.\nTo check whether a specific SIM is activated:\nClick\nManage my fleet\nfrom your account page (\n",(0,a.jsx)(n.a,{href:"https://eu.airvantage.net/accounts",children:"https://eu.airvantage.net/accounts"}),"\n)\nGo into\nMonitor > Systems\nUse the filtering capabilities to find your SIM using its Name, ICCID or other criteria\nIf the icon next to your SIM name is the one representing Inventory, your system is not activated yet.\nYou can check under\nMonitor > Operations\nwhether an activation operation has already been launched on your system. If so, you can click the operation to get more details.\nIs the APN correct?\nAPN configuration on your module may not match the authorized APNs on the sytem in AirVantage.\nIn order to double-check APN configuration for your system, go to its\nSystem Details\npage and look for the\nAuthorized APNs\nfield in the\nSystem Info\nwidget.\nThe default APN for\nSW Advanced / SW Essentials\nis\ninternet.swir\n.\nThe default APN for\nReady-to-Connect eSIMs\nis\nfota.swir\n(Cat-1+ devices) or\nlp.fota.swir\n(LPWA devices).\nA badly configured APN or an APN not allocating the expected fixed IP address will result into the device not being able to communicate or receive data.\nAre SW Advanced SIM pre-requisites met?\nIf you are using a\nSW Advanced\nSIM, your module may not be configured properly. We recommend to check the following pre-requisites:\nThe SIM Application Toolkit (STK) is active on the module\nThe module is configured to run automatic network selection\nGPRS/Packet data auto attachment mode is active on the module (for\nSmart SIM Advanced\n)\nA complete list of module prerequisites is described in the\nSierra Wireless Device requirements\ndocument.\nAre you roaming on an LTE-only network?\nIf you are not able to attach on specific LTE only networks, such as Verizon, Sprint in the US or KDDI in Japan, you may want to check the options that you have activated on your systems. If you have activated some Circuit Switch related options, those networks will not be available as we can only provide data services when roaming to those networks. On the contrary, if you activate only data services options, we optimize coverage by adding the capability to roam on those networks. For more information, please refer to\nHow to Change Provisioning Options?\nI cannot activate my Verizon SIM card\nTo activate a Verizon SIM, you must assign an IMEI to the system prior to activation. Otherwise, you will see the activation errors shown below.\nFor details on entering the IMEI, see\nHow to activate a Verizon SIM?\n.\nUsage is not reporting in the usage widgets\nPlease note that usage data is only updated in the usage widgets of the user interface every hour.\nUsage history and timeline will display the start (resp. stop) of data session in near real time (usually in a matter of seconds) and voice usages (VOICE, SMS, USSD) will be fresh from the last 15 minutes.\nI have ordered SIM cards but I haven\u2019t received them yet. What can I do?\nWhen you place a SIM order to us, a status of this order is accessible from your AirVantage account.\nAs soon as the order state is changed to\nshipped\n, we are supposed to send you an email with the information to track the parcel delivery (DHL or NorPost).\nHow often do I get an invoice?\nWe send an invoice on a monthly basis.\nI have lost an invoice. What can I do?\nYou can retrieve your past invoices from your AirVantage account in pdf format.\nHow can I check AirVantage or Connectivity services health?\nWe report all Sierra Wireless services\u2019 live availability at\n",(0,a.jsx)(n.a,{href:"http://status.sierrawireless.com",children:"http://status.sierrawireless.com"}),"\n. The status page can be easily accessed from the AirVantage login page\u2014click the\nServer Status\nlink.\nFor each service, information can be found on:\nLive operational state of the different components\nPlanned maintenance windows\nPast incidents\nWe also invite you to subscribe to receive notifications if one or more services are experiencing an outage and to be informed of any upcoming  maintenance. To subscribe, click\nSubscribe to updates\non the status page itself.\nFor complete information, see our\nCustomer Subscription Instructions\n(PDF).\nAmong the wide list of products proposed within the status page, we suggest that you subscribe to the ones that make sense for your AirVantage offer:\nSmart Connectivity\u2014pick the service components for your region that are included in your bundles\nSW Essentials3\u2014pick the service components for your region that are included in your bundles\nSW Essentials1\u2014pick the service components that are included in your bundles\nSW Essentials2\u2014pick the service components that are included in your bundles\nSW Essentials4\u2014pick the service components that are included in your bundles\nEnhanced Carrier Connectivity / MSO + Geographical selection\nAirVantage in any of the cases above. For AirVantage, select the components for your region: User interface, Web services API, Device Front End and eventually Data Push if you have subscribed to that option.\nDon\u2019t forget to clear all services for which you don\u2019t want to receive notifications not to be spammed by unrelated outages!\nCan I use an API to manage my SIM cards?\nYes, AirVantage provides an API you can use to perform some automation or integrate with another tool you are using.\nCheck out our\nGetting Started with AirVantage API\ndocument."]})]})}function l(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>s});var o=t(6540);let a={},i=o.createContext(a);function r(e){let n=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),o.createElement(i.Provider,{value:n},e.children)}}}]);